package com.watchparty.room;
import com.watchparty.auth.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.security.SecureRandom; import java.util.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import org.springframework.web.server.ResponseStatusException;
@Controller public class RoomController { final RoomRepository rooms; final UserRepository users; final SecureRandom random=new SecureRandom(); public RoomController(RoomRepository r,UserRepository u){rooms=r;users=u;}
 private User me(UserDetails d){return users.findByUsername(d.getUsername()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));}
 private Room member(String code,UserDetails d){Room r=rooms.findByCode(normalizeCode(code)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Room not found")); if(!r.hasMember(me(d)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Join this room first"); return r;}
 @GetMapping("/rooms") public String list(@AuthenticationPrincipal UserDetails d,Model m){m.addAttribute("rooms",rooms.findByMembers_Username(d.getUsername()));m.addAttribute("roomForm",new RoomForm());return "rooms";}
 @PostMapping("/rooms") public String create(@Valid @ModelAttribute("roomForm") RoomForm form,org.springframework.validation.BindingResult result,@AuthenticationPrincipal UserDetails d,Model m){if(result.hasErrors()){m.addAttribute("rooms",rooms.findByMembers_Username(d.getUsername()));return "rooms";}String code; do{code=String.format("%06d",random.nextInt(1_000_000));}while(rooms.findByCode(code).isPresent()); rooms.save(new Room(code,form.name.trim(),me(d),form.videoUrl==null?"":form.videoUrl.trim())); return "redirect:/room/"+code;}
 @GetMapping("/room/{code}") public String room(@PathVariable String code,@AuthenticationPrincipal UserDetails d,Model m){Room r=member(code,d);SettingsForm settings=new SettingsForm();settings.setName(r.getName());settings.setVideoUrl(r.getVideoUrl());m.addAttribute("room",r);m.addAttribute("settingsForm",settings);m.addAttribute("isHost",r.isHost(me(d)));return "room";}
 @PostMapping("/room/{code}/join") public String join(@PathVariable String code,@AuthenticationPrincipal UserDetails d){String normalized=normalizeCode(code);Room r=rooms.findByCode(normalized).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Room not found"));User u=me(d);if(!r.hasMember(u)){r.getMembers().add(u);rooms.save(r);}return "redirect:/room/"+normalized;}
 @PostMapping("/room/{code}/leave") public String leave(@PathVariable String code,@AuthenticationPrincipal UserDetails d){Room r=member(code,d);User u=me(d);if(r.isHost(u))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"The host cannot leave the room");r.getMembers().removeIf(member->member.getId().equals(u.getId()));rooms.save(r);return "redirect:/rooms";}
 @PostMapping("/room/{code}/settings") public String settings(@PathVariable String code,@Valid @ModelAttribute("settingsForm") SettingsForm form,org.springframework.validation.BindingResult result,@AuthenticationPrincipal UserDetails d,Model m){Room r=member(code,d);if(!r.isHost(me(d)))throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(result.hasErrors()){m.addAttribute("room",r);m.addAttribute("isHost",true);return "room";}r.setName(form.name.trim());r.setVideoUrl(form.videoUrl==null?"":form.videoUrl.trim());rooms.save(r);return "redirect:/room/"+code;}
 @ResponseBody @GetMapping("/api/rooms/{code}/members") public List<MemberView> members(@PathVariable String code,@AuthenticationPrincipal UserDetails d){return member(code,d).getMembers().stream().map(u->new MemberView(u.getDisplayName(),u.getUsername())).toList();}
 public record MemberView(String displayName,String username){}
 private String normalizeCode(String code){String normalized=code==null?"":code.trim().toUpperCase(Locale.ROOT);if(!normalized.matches("[A-Z0-9]{6}"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Room code must contain 6 letters or numbers");return normalized;}
 public static class RoomForm{@NotBlank @Size(max=120) public String name; @Size(max=1000) public String videoUrl; public String getName(){return name;} public void setName(String v){name=v;} public String getVideoUrl(){return videoUrl;} public void setVideoUrl(String v){videoUrl=v;}}
 public static class SettingsForm extends RoomForm{}
}
